import{_ as t,o,c as d,ag as r}from"./chunks/framework.D9ghT4bC.js";const h=JSON.parse('{"title":"代码规范","description":"","frontmatter":{"title":"代码规范"},"headers":[],"relativePath":"zh/UncivCN/Coding-standards.md","filePath":"zh/UncivCN/Coding-standards.md"}'),c={name:"zh/UncivCN/Coding-standards.md"};function n(s,e,i,a,l,u){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="代码规范-uncivcn-分支" tabindex="-1">代码规范（UncivCN 分支） <a class="header-anchor" href="#代码规范-uncivcn-分支" aria-label="Permalink to &quot;代码规范（UncivCN 分支）&quot;">​</a></h1><blockquote><p><strong>本文件是 UncivCN 分支的工程规范汇总，全部条目均来自实际踩坑教训。</strong> 修改文档、文档生成器、unique 定义或翻译相关代码前，<strong>必须先通读本文</strong>。</p></blockquote><h2 id="一、文档站维护-vitepress-vs-上游-mkdocs" tabindex="-1">一、文档站维护（VitePress vs 上游 mkdocs） <a class="header-anchor" href="#一、文档站维护-vitepress-vs-上游-mkdocs" aria-label="Permalink to &quot;一、文档站维护（VitePress vs 上游 mkdocs）&quot;">​</a></h2><p>UncivCN 分支的文档站（<code>docs-vitepress/</code>）使用 VitePress（弃 mkdocs：不支持中文搜索）； 上游仍用 mkdocs。两者语法不兼容，维护时务必注意以下<strong>踩坑记录</strong>：</p><table tabindex="0"><thead><tr><th>项目</th><th>上游 mkdocs</th><th>UncivCN VitePress</th></tr></thead><tbody><tr><td>容器（admonition）</td><td><code>!!! note</code> + 内容 <strong>4 空格缩进</strong></td><td><code>::: note</code> + 内容<strong>禁止缩进</strong></td></tr><tr><td>提示块类型</td><td>admonition 全类型</td><td>内置 tip/info/warning/danger/details；note 需自定义注册</td></tr><tr><td>缩写悬浮提示</td><td><code>*[param]: 说明</code> 自动渲染 abbr</td><td>不识别，改用参数说明表</td></tr><tr><td>文档生成器输出</td><td>mkdocs 格式（缩进容器）</td><td>VitePress 格式（无缩进容器）</td></tr></tbody></table><h3 id="写作铁律-全部为实际踩过的坑" tabindex="-1">写作铁律（全部为实际踩过的坑） <a class="header-anchor" href="#写作铁律-全部为实际踩过的坑" aria-label="Permalink to &quot;写作铁律（全部为实际踩过的坑）&quot;">​</a></h3><ol><li><strong>容器内容禁止缩进</strong>：VitePress 容器内 4 空格/tab 缩进会被 markdown 当作代码块 渲染为 <code>&lt;pre&gt;</code>，pre 不自动换行，大段落向右撑破屏幕。生成器输出、手工文档均同。</li><li><strong>JSON 字面量不翻译</strong>：unique 文本、参数名、Countables 文本/示例必须保留英文原文—— 游戏按文本逐字匹配 <code>UniqueType.uniqueTypeMap</code> 才能生效，翻译后模组制作者照抄即失效。</li><li><strong>同名参数编号化</strong>：unique 标题中重复参数按 <code>[amount] [amount]</code> → <code>[amount]-[amount2]</code> 编号显示（与翻译模板 <code>getTranslatable()</code> 一致），读者可区分；示例行仍用原始文本 （可直接复制进模组 JSON）。</li><li><strong>自动生成文档只许改生成器源码</strong>：改完运行 <code>./gradlew desktop:generateDocs</code>， 严禁人工编辑产物。</li><li><strong>参数表多行说明</strong>：docDescription 含换行时会撑破 markdown 表格，生成器已将其 替换为 <code>&lt;br&gt;</code>，手工维护表格时同样处理。</li></ol><h2 id="二、自动生成文档清单" tabindex="-1">二、自动生成文档清单 <a class="header-anchor" href="#二、自动生成文档清单" aria-label="Permalink to &quot;二、自动生成文档清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产物</th><th>生成器</th><th>维护方式</th></tr></thead><tbody><tr><td><code>docs/Modders/uniques.md</code></td><td><code>UniqueDocsWriter.write()</code></td><td><strong>整体自动</strong>，改生成器源码</td></tr><tr><td><code>docs/zh/Modders/uniques.md</code></td><td><code>UniqueDocsWriter.writeChinese()</code></td><td><strong>整体自动</strong>，改生成器源码</td></tr><tr><td><code>docs/Modders/Unique-parameters.md</code></td><td><code>UniqueDocsWriter.writeCountables()</code></td><td>marker 区间自动，其余人工</td></tr><tr><td><code>docs/zh/Modders/Unique-parameters.md</code></td><td><code>UniqueDocsWriter.writeCountables()</code></td><td>marker 区间自动（中文翻译内置在生成器），其余人工</td></tr><tr><td><code>docs/Modders/Mod-file-structure/6-MergeActions.md</code></td><td><code>MergeActionDocsWriter</code></td><td><strong>整体自动</strong></td></tr><tr><td><code>docs/Modders/Creating-a-UI-skin.md</code></td><td><code>UiElementDocsWriter</code></td><td>marker 区间自动，其余人工</td></tr><tr><td><code>docs/zh/Modders/Creating-a-UI-skin.md</code></td><td><code>UiElementDocsWriter</code></td><td>marker 区间自动，其余人工</td></tr><tr><td>其余 <code>docs/</code>、<code>docs/zh/</code> 页面</td><td>—</td><td>人工维护</td></tr></tbody></table><p><strong>原则</strong>：自动生成的文档只通过「改生成器源码 + 运行 <code>./gradlew desktop:generateDocs</code>」维护， <strong>严禁人工编辑产物</strong>。生成器内置的中文翻译（<code>docsSentence</code> / <code>countablesTranslate</code>） 同样随源码维护。</p><p>本地预览：双击 <code>docs-vitepress/build.bat</code>（构建 / 打开现有 / 重建重启三选一， 服务器空闲 5 分钟自动退出）。</p><h2 id="三、unique-与翻译规范" tabindex="-1">三、unique 与翻译规范 <a class="header-anchor" href="#三、unique-与翻译规范" aria-label="Permalink to &quot;三、unique 与翻译规范&quot;">​</a></h2><ol><li><strong>docDescriptionZh 与 docDescription 同处定义</strong>：新增或修改 <code>UniqueType</code> / <code>UniqueParameterType</code> 的 <code>docDescription</code> 时，<strong>必须同时</strong>写 <code>docDescriptionZh</code> （中文说明），文档生成器自动读取；缺中文时回退英文。禁止在生成器里维护 大翻译映射表。</li><li><strong>JSON 字面量不翻译</strong>（见写作铁律 2）：unique 文本、参数名、Countables 的 文本/示例是模组 JSON 字面量，保持英文原文；只翻译说明性文字。</li><li><strong>翻译接口分流</strong>： <ul><li>游戏内显示字符串 → 翻译模板（<code>template.properties</code> / <code>Simplified_Chinese.properties</code>）</li><li>纯文档字符串（<code>docDescription</code>、UniqueTarget 文档说明、Countables 说明）→ 源码字段（<code>docDescriptionZh</code>）或生成器内置翻译（<code>docsSentence</code> / <code>countablesTranslate</code>）</li></ul></li><li><strong>唯一标识一致性</strong>：翻译 key 用 <code>getTranslatable()</code>（重复占位符编号化）， 文档标题展示编号化形式，但示例永远用原始文本。</li></ol><h2 id="四、分支规范" tabindex="-1">四、分支规范 <a class="header-anchor" href="#四、分支规范" aria-label="Permalink to &quot;四、分支规范&quot;">​</a></h2><ul><li><strong>版本号</strong> = 上游版本 + CN 子版本号（如上游 4.21.5 → UncivCN 4.21.5.1；同一上游版本可发 <code>.1</code>/<code>.2</code>/<code>.3</code>…，如 4.20.8.1 → 4.20.8.4；跟进新上游后子版本号从 <code>.1</code> 重新开始）， 定义在 <code>buildSrc/src/main/kotlin/BuildConfig.kt</code></li><li><strong>增量实现</strong>：新功能不修改上游既有行为，关闭相关选项后与上游一致</li><li><strong>文档镜像</strong>：<code>docs/zh/</code> 与英文区一一对应（同一路径即对应翻译）； 中文独有内容只放 <code>docs/zh/UncivCN/</code></li><li><strong>中文一等公民</strong>：新 UI 字符串必须进翻译模板；新 unique 说明必须同时提供中文</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li>[与上游差异（游戏内容对照）./Differences)</li><li>[UncivCN 更新日志./Changelog)</li></ul>',17)])])}const m=t(c,[["render",n]]);export{h as __pageData,m as default};
